contracts/CEToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title CEToken (Community Engagement Token)
 * @dev ERC-5192 Minimal Soulbound Token Implementation for Eco Energy Hub.
 * Tokens are non-transferable and represent governance rights earned through energy actions.
 */
contract CEToken {
    string public name = "Community Engagement Token";
    string public symbol = "CET";
    uint8 public decimals = 18;

    address public owner;
    mapping(address => uint256) private _balances;
    mapping(address => bool) public isVerifiedIdentity;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Locked(uint256 tokenId);
    event IdentityVerified(address indexed account);

    modifier onlyOwner() {
        require(msg.sender == owner, "CET: Caller is not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function verifyIdentity(address account) external onlyOwner {
        isVerifiedIdentity[account] = true;
        emit IdentityVerified(account);
    }

    function mint(address to, uint256 amount) external onlyOwner {
        require(isVerifiedIdentity[to], "CET: Account identity not verified");
        _balances[to] += amount;
        emit Transfer(address(0), to, amount);
        emit Locked(amount);
    }

    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }

    // Block all transfers (Soulbound enforcement)
    function transfer(address, uint256) external pure returns (bool) {
        revert("CET: Soulbound token - transfers disabled");
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("CET: Soulbound token - transfers disabled");
    }
}

contracts/GovernorQV.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface ICEToken {
    function balanceOf(address account) external view returns (uint256);
    function isVerifiedIdentity(address account) external view returns (bool);
}

/**
 * @title GovernorQV
 * @dev Quadratic Voting Governor where n votes cost n^2 Voice Credits (VCs).
 */
contract GovernorQV {
    struct Proposal {
        uint256 id;
        address proposer;
        string descriptionHash;
        uint256 votingEnds;
        uint256 netQuadraticVotes;
        bool executed;
        bool canceled;
    }

    ICEToken public immutable ceToken;
    uint256 public proposalCount;
    uint256 public constant PROPOSAL_DEPOSIT = 10 * 10**18; // 10 CET
    uint256 public constant VOTING_DURATION = 7 days;

    mapping(uint256 => Proposal) public proposals;
    // proposalId => voter => quadratic votes cast
    mapping(uint256 => mapping(address => uint256)) public votesCast;

    event ProposalCreated(uint256 indexed id, address indexed proposer, string descriptionHash);
    event VoteCast(uint256 indexed proposalId, address indexed voter, uint256 votes, uint256 vcCost);

    constructor(address _ceToken) {
        ceToken = ICEToken(_ceToken);
    }

    function createProposal(string calldata descriptionHash) external returns (uint256) {
        require(ceToken.balanceOf(msg.sender) >= PROPOSAL_DEPOSIT, "GovernorQV: Insufficient CET deposit");

        proposalCount++;
        proposals[proposalCount] = Proposal({
            id: proposalCount,
            proposer: msg.sender,
            descriptionHash: descriptionHash,
            votingEnds: block.timestamp + VOTING_DURATION,
            netQuadraticVotes: 0,
            executed: false,
            canceled: false
        });

        emit ProposalCreated(proposalCount, msg.sender, descriptionHash);
        return proposalCount;
    }

    /**
     * @dev Casts n quadratic votes. Cost in Voice Credits = n^2.
     */
    function castVote(uint256 proposalId, uint256 votes) external {
        Proposal storage proposal = proposals[proposalId];
        require(block.timestamp < proposal.votingEnds, "GovernorQV: Voting ended");
        require(ceToken.isVerifiedIdentity(msg.sender), "GovernorQV: Unverified voter");

        uint256 vcCost = votes * votes; // Quadratic Cost Formula: Cost = n^2
        require(ceToken.balanceOf(msg.sender) >= vcCost, "GovernorQV: Insufficient Voice Credits");

        votesCast[proposalId][msg.sender] += votes;
        proposal.netQuadraticVotes += votes;

        emit VoteCast(proposalId, msg.sender, votes, vcCost);
    }
}

contracts/TimelockGuardian.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title TimelockGuardian
 * @dev Enforces a 48-hour challenge period before execution and provides pause-only authority to a 3-of-5 multisig guardian.
 */
contract TimelockGuardian {
    uint256 public constant TIMELOCK_DELAY = 48 hours;

    address[5] public guardians;
    bool public isPaused;
    mapping(bytes32 => uint256) public queuedTransactions;
    mapping(bytes32 => mapping(address => bool)) public pauseConfirmations;
    uint256 public pauseVotes;

    event TransactionQueued(bytes32 indexed txHash, uint256 executionTime);
    event TransactionExecuted(bytes32 indexed txHash);
    event EmergencyPaused(address indexed guardian);

    modifier onlyGuardian() {
        bool isG = false;
        for (uint256 i = 0; i < 5; i++) {
            if (guardians[i] == msg.sender) { isG = true; break; }
        }
        require(isG, "Timelock: Caller is not guardian");
        _;
    }

    constructor(address[5] memory _guardians) {
        guardians = _guardians;
    }

    function queueTransaction(bytes32 txHash) external {
        uint256 executionTime = block.timestamp + TIMELOCK_DELAY;
        queuedTransactions[txHash] = executionTime;
        emit TransactionQueued(txHash, executionTime);
    }

    function emergencyPause() external onlyGuardian {
        require(!pauseConfirmations[bytes32(0)][msg.sender], "Timelock: Already voted");
        pauseConfirmations[bytes32(0)][msg.sender] = true;
        pauseVotes++;

        if (pauseVotes >= 3) { // 3-of-5 Threshold
            isPaused = true;
            emit EmergencyPaused(msg.sender);
        }
    }
}

